<script setup lang="ts">
import { computed, ref } from 'vue'
const nav=ref('Dashboard'), period=ref('Monthly'), query=ref(''), status=ref('All'), selected=ref<number|null>(26), notice=ref(''), dialog=ref<HTMLDialogElement|null>(null), customer=ref(''), product=ref(''), quantity=ref(1), price=ref(100)
const rows=ref([{id:'04910',customer:'Ryan Korsgaard',product:'Ergo Office Chair',status:'Success',qty:12,price:3450},{id:'04911',customer:'Madelyn Lubin',product:'Sunset Desk 02',status:'Success',qty:20,price:2980},{id:'04912',customer:'Abram Bergson',product:'Eco Bookshelf',status:'Pending',qty:22,price:1750},{id:'04913',customer:'Phillip Mango',product:'Green Leaf Desk',status:'Refunded',qty:24,price:1950}])
const visible=computed(()=>rows.value.filter(r=>(status.value==='All'||r.status===status.value)&&`${r.customer} ${r.product} ${r.id}`.toLowerCase().includes(query.value.toLowerCase())))
const heights=computed(()=>Array.from({length:60},(_,i)=>3+Math.round(Math.abs(Math.sin(i*.63)*(period.value==='Weekly'?5:9))+Math.abs(Math.sin(i*.21)*2))))
const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n)
function exportCSV(){const csv='ID,Customer,Product,Status,Quantity,Unit price,Total\n'+visible.value.map(r=>[r.id,r.customer,r.product,r.status,r.qty,r.price,r.qty*r.price].join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='spark-analytics-demo.csv';a.click();URL.revokeObjectURL(a.href);notice.value='Demo CSV exported'}
function add(){if(!customer.value.trim()||!product.value.trim())return;rows.value.unshift({id:String(4910+rows.value.length),customer:customer.value,product:product.value,status:'Pending',qty:quantity.value,price:price.value});dialog.value?.close();notice.value='Local transaction added. Nothing charged.';customer.value='';product.value=''}
const kpis=[{label:'Total revenue',value:'$20,320'},{label:'Total orders',value:'10,320'},{label:'New customers',value:'4,305'},{label:'Conversion rate',value:'3.9%'}]
</script>
<template>
<section class="reference-dashboard sparkdash" aria-label="Orange agency analytics demo"><aside class="spark-sidebar"><div class="spark-logo">◧ &nbsp; <b>Spark Pixel Team</b><small style="display:block;margin:2px 0 0">Agency workspace</small></div><small>Main Menu</small><button v-for="item in ['Dashboard','Products','Transactions','Reports & Analytics','Messages','Team Performance','Campaigns']" :key="item" :class="{active:nav===item}" @click="nav=item">{{item}}</button><small>Customers</small><button v-for="item in ['Customer List','Channels','Order Management']" :key="item" @click="nav=item" :class="{active:nav===item}">{{item}}</button><small>Management</small><button v-for="item in ['Roles & Permissions','Billing & Subscription','Integrations']" :key="item" @click="nav=item" :class="{active:nav===item}">{{item}}</button><small>Settings</small><button @click="notice='Demo support is local only.'">Customer Support</button><button @click="notice='No external account connected.'">System Settings</button><div class="spark-profile">◉ &nbsp; Alex Morgan<small style="display:block">Pro Plan · Demo</small></div></aside><main class="spark-main"><header class="spark-top"><span>{{nav}} › <b style="color:#ff811b">Overview</b></span><input v-model="query" aria-label="Global search transactions" placeholder="Search..."><button aria-label="Show analytics notifications" @click="notice='No new notifications'">♧</button><span class="ref-avatar">AM</span></header><div class="ref-heading"><h2>{{nav==='Dashboard'?'Welcome back, Alex':nav}}</h2><div class="ref-tools"><select aria-label="Time granularity" v-model="period"><option>Weekly</option><option>Monthly</option><option>Yearly</option></select><button @click="notice='Showing sample data for 6 November 2026'">▣ 6 Nov 2026</button><button class="ref-primary" @click="exportCSV">↥ Export CSV</button></div></div><div class="spark-kpis"><article v-for="k in kpis" :key="k.label" class="spark-kpi"><small>{{k.label}}</small><strong>{{k.value}}</strong><div class="spark-mini"><i v-for="i in 7" :key="i"></i></div><p>↗ +0.94% last year</p></article></div><div class="spark-grid"><article class="spark-card"><h3>SALES TREND ⓘ</h3><div class="spark-chart-head"><span>Total Revenue: <strong>$20,320</strong></span><div class="spark-tabs"><button v-for="p in ['Weekly','Monthly','Yearly']" :key="p" :class="{active:period===p}" @click="period=p">{{p}}</button></div></div><div class="spark-chart"><div class="spark-axis"><span v-for="n in [60,50,40,30,20,10,0]" :key="n">{{n}}k</span></div><div class="spark-pixels" role="img" aria-label="Orange pixel histogram showing sample sales across 12 months"><div v-for="(height,i) in heights" :key="period+'-'+i" class="spark-pixel-col" @mouseenter="selected=i" @mouseleave="selected=null"><i v-for="j in height" :key="j" class="spark-pixel" :class="{existing:j>height*.7}"></i></div></div><div class="spark-months"><span v-for="m in ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC']" :key="m">{{m}}</span></div><div class="spark-tooltip" v-if="selected!==null">{{['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Math.floor(selected/5)]}} 2026<small>◦ New User &nbsp;{{heights[selected]*2}}k</small><small style="color:#ff811b">• Existing User &nbsp;{{heights[selected]}}k</small></div></div><p style="font-size:9px;margin-top:12px">□ New user &nbsp; <span style="color:#ff811b">■ Existing user</span></p></article><article class="spark-card"><h3>REVENUE BREAKDOWN ⓘ</h3><p style="margin:17px 0 5px;font-size:10px">Revenue by category</p><strong style="font:600 22px monospace">$20,320</strong><button class="spark-ai" style="width:100%;text-align:left" @click="notice='Sample insight: furniture drives 54% of revenue. No AI request was sent.'">✦ Get AI insight for better analysis</button><div class="spark-revenue"><button v-for="(h,i) in [40,57,31,68,45,32,49,40,58,44,66,35]" :key="i" :style="{height:h+'%'}" :aria-label="'Category '+(i+1)+' revenue'" @click="notice='Category '+(i+1)+': '+money(h*50)"></button></div><div class="fix-labels"><span>1 JAN</span><span>30 JAN 2026</span></div></article></div><article class="spark-card"><div class="ref-heading" style="margin-bottom:10px"><h3 style="border:0;padding:0">RECENT TRANSACTIONS ⓘ</h3><div class="ref-tools"><input v-model="query" aria-label="Search transactions" placeholder="Search transactions..." style="font-size:9px"><select v-model="status" aria-label="Transaction status filter" style="font-size:9px"><option>All</option><option>Success</option><option>Pending</option><option>Refunded</option></select><button class="ref-primary" style="font-size:9px" @click="dialog?.showModal()">+ Add Transaction</button></div></div><div class="ref-table-scroll"><table><thead><tr><th>ID</th><th>Customer</th><th>Product</th><th>Status</th><th class="number">Qty</th><th class="number">Unit price</th><th class="number">Total revenue</th><th>Actions</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>#{{r.id}}</td><td>{{r.customer}}</td><td>{{r.product}}</td><td><span class="spark-status" :class="r.status.toLowerCase()">● {{r.status}}</span></td><td class="number">{{r.qty}}</td><td class="number">{{money(r.price)}}</td><td class="number">{{money(r.qty*r.price)}}</td><td><button :aria-label="'View transaction '+r.id" @click="notice=`#${r.id} · ${r.customer} · ${money(r.qty*r.price)} · ${r.status}`" style="padding:1px 5px">•••</button></td></tr><tr v-if="!visible.length"><td colspan="8">No matching transactions.</td></tr></tbody></table></div></article><p v-if="notice" class="ref-notice" role="status">{{notice}}</p><p style="font-size:9px;margin-top:15px">Fictitious local demo · No account, customer or payment connected</p></main><dialog ref="dialog" class="ref-dialog"><form @submit.prevent="add"><h3>Add demo transaction</h3><label>Customer<input v-model="customer" required></label><label>Product<input v-model="product" required></label><label>Quantity<input v-model="quantity" type="number" min="1" required></label><label>Unit price (USD)<input v-model="price" type="number" min="0" step=".01" required></label><div class="ref-tools"><button type="button" @click="dialog?.close()">Cancel</button><button type="submit" class="ref-primary">Add local row</button></div></form></dialog></section>
</template>
